        fontSize: 15, fontWeight: 700, letterSpacing: 0.5,
        background: "linear-gradient(135deg, #4FFFB0 0%, #00B4D8 100%)",
        color: "#0A0C10",
        boxShadow: "0 4px 24px rgba(79,255,176,0.25)",
